mapper.select:
SELECT i.ID AS id, i.DEPLOYMENT_ID AS deploymentId, i.BUSINESS_KEY AS businessKey, i.EXECUTION_STATUS AS executionStatus, i.CURRENT_NODE_ID AS currentNodeId, i.STATE_JSON AS stateJson, i.ENV_CODE AS envCode, i.DELETED AS deleted, i.CREATE_USER AS createUser, i.CREATE_TIME AS createTime, i.UPDATE_USER AS updateUser, i.UPDATE_TIME AS updateTime FROM AST_FLOW_INSTANCE i WHERE (i.DELETED = 0 OR i.DELETED IS NULL)
AND i.DEPLOYMENT_ID = #{req.deploymentId}
AND i.BUSINESS_KEY LIKE CONCAT('%', #{req.businessKey}, '%')
AND i.EXECUTION_STATUS = #{req.executionStatus}
AND i.CURRENT_NODE_ID = #{req.currentNodeId}
ORDER BY i.UPDATE_TIME DESC, i.ID DESC
